	"""
def maximumProduct(nums: Any) -> object {
    nums = sorted(nums);
    first_option = nums[0] * nums[1] * nums[-1];
    second_option = nums[-3] * nums[-2] * nums[-1];
    return first_option if (first_option > second_option) else second_option;
}

"""
    Counts how many unique names can be created from the
    combinations of each lists contained in the passed dictionary.
    """
def count_possibilities(dic: Any) -> object {
    total = 1;
    for (key, value) in dic.items() {
        total *= len(value);
    }
    return total;
}

"""
    Takes a raw number of bytes and returns a humanized filesize.
    """
def file_size(
    value: Any, fmt: Any = "{value:.1f} {suffix}", si: Any = False
) -> object {
    if si {
        base = 1000;
        suffixes = ("B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB");
    } else {
        base = 1024;
        suffixes = ("B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB");
    }
    max_suffix_index = len(suffixes) - 1;
    for (i, suffix) in enumerate(suffixes) {
        unit = base ** (i + 1);
        if ((value < unit) or (i == max_suffix_index)) {
            return fmt.format(value=((base * value) / unit), suffix=suffix);
        }
    }
}

